			b.WriteString(s)
		case p.atCRLF():
			b.WriteString("\r\n")
			p.pos += 2
		case c == '\n':
			b.WriteByte(c)
			p.pos++
		case isDisallowedControl(c):
			return "", p.errorf("control character in multi-line string")
		default:
