package toml

import (
	"errors"
	"reflect"
	"testing"
)

// arrayLeaf is the tagged model for an array value, shared by the array and inline tests.
func arrayLeaf(elems ...any) map[string]any {
	if elems == nil {
		elems = []any{}
	}
	return map[string]any{"type": "array", "value": elems}
}

func TestDecodeBuildsArrays(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  map[string]any
	}{
		{
			name:  "empty array",
			input: "a = []\n",
			want:  map[string]any{"a": arrayLeaf()},
		},
		{
			name:  "one element",
			input: "a = [1]\n",
			want:  map[string]any{"a": arrayLeaf(intLeaf("1"))},
		},
		{
			name:  "two integers",
			input: "xs = [1, 2]\n",
			want:  map[string]any{"xs": arrayLeaf(intLeaf("1"), intLeaf("2"))},
		},
		{
			name:  "spaces and tabs around elements",
			input: "a = [ 1 ,\t2 ]\n",
			want:  map[string]any{"a": arrayLeaf(intLeaf("1"), intLeaf("2"))},
		},
		{
			name:  "mixed types in one array",
			input: "a = [1, \"x\", true, 1.5]\n",
			want: map[string]any{"a": arrayLeaf(
				intLeaf("1"),
				stringLeaf("x"),
				map[string]any{"type": "bool", "value": "true"},
				map[string]any{"type": "float", "value": "1.5"},
			)},
		},
		{
			name:  "trailing comma",
			input: "a = [1, 2,]\n",
			want:  map[string]any{"a": arrayLeaf(intLeaf("1"), intLeaf("2"))},
		},
		{
			name:  "nested arrays",
			input: "a = [[1], [2, 3], []]\n",
			want: map[string]any{"a": arrayLeaf(
				arrayLeaf(intLeaf("1")),
				arrayLeaf(intLeaf("2"), intLeaf("3")),
				arrayLeaf(),
			)},
		},
		{
